using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using MiniStore.Domain.Entities;
namespace MiniStore.Infrastructure.Persistence.Configurations;
public sealed class PurchaseAgreementConfiguration : IEntityTypeConfiguration<PurchaseAgreement>, IEntityTypeConfiguration<PurchaseAgreementLine>, IEntityTypeConfiguration<PurchaseTemplate>, IEntityTypeConfiguration<PurchaseTemplateLine>
{
 public void Configure(EntityTypeBuilder<PurchaseAgreement>b){b.HasKey(x=>x.Id);b.Property(x=>x.AgreementNumber).HasMaxLength(50).IsRequired();b.Property(x=>x.CurrencyCode).HasMaxLength(3).IsRequired();b.Property(x=>x.PaymentTermsSnapshot).HasMaxLength(500);b.Property(x=>x.CreatedByUserId).HasMaxLength(450).IsRequired();b.Property(x=>x.ActivatedByUserId).HasMaxLength(450);b.Property(x=>x.CancellationReason).HasMaxLength(1000);b.Property(x=>x.RowVersion).IsRowVersion();b.HasIndex(x=>x.AgreementNumber).IsUnique();b.HasIndex(x=>x.SupplierQuotationId).IsUnique();b.HasOne<PurchaseSourcingEvent>().WithMany().HasForeignKey(x=>x.PurchaseSourcingEventId).OnDelete(DeleteBehavior.Restrict);b.HasOne<SupplierQuotation>().WithMany().HasForeignKey(x=>x.SupplierQuotationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Supplier>().WithMany().HasForeignKey(x=>x.SupplierId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Warehouse>().WithMany().HasForeignKey(x=>x.WarehouseId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Lines).WithOne().HasForeignKey(x=>x.PurchaseAgreementId).OnDelete(DeleteBehavior.Cascade);}
 public void Configure(EntityTypeBuilder<PurchaseAgreementLine>b){b.HasKey(x=>x.Id);b.Property(x=>x.MaximumQuantity).HasPrecision(18,6);b.Property(x=>x.UnitFactorToBase).HasPrecision(24,12);b.Property(x=>x.UnitPrice).HasPrecision(24,8);b.Property(x=>x.DiscountPercent).HasPrecision(9,4);b.Property(x=>x.TaxPercent).HasPrecision(9,4);b.Property(x=>x.ProductCodeSnapshot).HasMaxLength(100).IsRequired();b.Property(x=>x.ProductNameSnapshot).HasMaxLength(250).IsRequired();b.Property(x=>x.UnitNameSnapshot).HasMaxLength(100).IsRequired();b.HasIndex(x=>new{x.PurchaseAgreementId,x.SupplierQuotationLineId}).IsUnique();b.HasOne<SupplierQuotationLine>().WithMany().HasForeignKey(x=>x.SupplierQuotationLineId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Product>().WithMany().HasForeignKey(x=>x.ProductId).OnDelete(DeleteBehavior.Restrict);b.HasOne<MeasurementUnit>().WithMany().HasForeignKey(x=>x.MeasurementUnitId).OnDelete(DeleteBehavior.Restrict);}
 public void Configure(EntityTypeBuilder<PurchaseTemplate>b){b.HasKey(x=>x.Id);b.Property(x=>x.TemplateNumber).HasMaxLength(50).IsRequired();b.Property(x=>x.Name).HasMaxLength(150).IsRequired();b.Property(x=>x.CreatedByUserId).HasMaxLength(450).IsRequired();b.Property(x=>x.RowVersion).IsRowVersion();b.HasIndex(x=>x.TemplateNumber).IsUnique();b.HasOne<PurchaseOrder>().WithMany().HasForeignKey(x=>x.SourcePurchaseOrderId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Supplier>().WithMany().HasForeignKey(x=>x.SupplierId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Warehouse>().WithMany().HasForeignKey(x=>x.WarehouseId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Lines).WithOne().HasForeignKey(x=>x.PurchaseTemplateId).OnDelete(DeleteBehavior.Cascade);}
 public void Configure(EntityTypeBuilder<PurchaseTemplateLine>b){b.HasKey(x=>x.Id);b.Property(x=>x.RequestedQuantity).HasPrecision(18,6);b.Property(x=>x.UnitFactorToBase).HasPrecision(24,12);b.HasIndex(x=>new{x.PurchaseTemplateId,x.ProductId,x.MeasurementUnitId}).IsUnique();b.HasOne<Product>().WithMany().HasForeignKey(x=>x.ProductId).OnDelete(DeleteBehavior.Restrict);b.HasOne<MeasurementUnit>().WithMany().HasForeignKey(x=>x.MeasurementUnitId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Supplier>().WithMany().HasForeignKey(x=>x.SuggestedSupplierId).OnDelete(DeleteBehavior.Restrict);}
}
